private val Ink = Color(0xFF172723); private val Muted = Color(0xFF798780); private val Green = Color(0xFF167C68); private val CanvasBg = Color(0xFFF3F6F2); private val Red = Color(0xFFE25555); private val Blue = Color(0xFF4C83D8); private val Amber=Color(0xFFCA9241)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); val db=LotteryDatabase(applicationContext); db.importAssetIfEmpty(applicationContext); scheduleDrawSync(applicationContext); setContent { App(db) } }
}

@Composable fun App(db: LotteryDatabase) {
    val context= LocalContext.current; val scope= rememberCoroutineScope()
    var page by remember { mutableIntStateOf(0) }; var years by remember { mutableIntStateOf(1) }; var amount by remember { mutableIntStateOf(3) }; var mode by remember { mutableStateOf("综合模型") }; var tickets by remember { mutableStateOf<List<Ticket>>(emptyList()) }
    var draws by remember { mutableStateOf(db.readAll()) }; var syncing by remember { mutableStateOf(false) }; var syncMessage by remember { mutableStateOf("") }; var syncTime by remember { mutableStateOf(context.getSharedPreferences("sync",0).getString("last_ok",null).orEmpty()) }
    fun sync() { if(syncing)return; syncing=true; syncMessage="正在连接中国福彩网…"; scope.launch { val result=withContext(Dispatchers.IO){runCatching { OfficialDrawSync(db).syncLatest() }}; result.onSuccess { updated -> draws=db.readAll(); syncTime=java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.CHINA).format(java.util.Date()); context.getSharedPreferences("sync",0).edit().putString("last_ok",syncTime).apply(); syncMessage="同步成功 · 更新 $updated 期" }.onFailure { syncMessage="同步失败：${it.message?.take(70) ?: "网络连接错误"}" }; syncing=false } }
    MaterialTheme(colorScheme=lightColorScheme(primary=Green,background=CanvasBg,surface=Color.White)) {
        Scaffold(containerColor=CanvasBg,bottomBar={NavigationBar(containerColor=Color.White){listOf("首页" to "⌂","数据分析" to "▥","历史数据" to "▤","智能选号" to "✦").forEachIndexed{i,item->NavigationBarItem(selected=page==i,onClick={page=i},icon={Text(item.second,fontSize=20.sp)},label={Text(item.first,fontSize=11.sp)})}}}) { pad ->
            when(page){
                0->Home(draws,tickets,years,amount,mode,{years=it},{amount=it},{mode=it},{tickets=LotteryEngine.generate(draws,amount,years,mode)},Triple(syncing,syncMessage,syncTime),::sync)
                1->Analysis(draws,years,{years=it})
                2->History(draws,syncing,syncMessage,syncTime,::sync)
                else->Smart(draws,years,amount,mode,{years=it},{amount=it},{mode=it},{tickets=LotteryEngine.generate(draws,amount,years,mode)},{min,max -> tickets=LotteryEngine.generate(draws,amount,years,mode,sumRange=min..max,oddRange=0..6) },tickets)
            }
        }
    }
}

@Composable fun Header(title:String,subtitle:String?=null){Column(Modifier.fillMaxWidth().padding(horizontal=20.dp,vertical=16.dp)){Text(title,fontSize=26.sp,fontWeight=FontWeight.Bold,color=Ink);if(subtitle!=null)Text(subtitle,fontSize=13.sp,color=Muted,modifier=Modifier.padding(top=4.dp))}}
@Composable fun PageScroll(content:@Composable ColumnScope.()->Unit){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()),content=content)}
@Composable fun CardBox(content:@Composable ColumnScope.()->Unit){Column(Modifier.fillMaxWidth().padding(horizontal=16.dp,vertical=7.dp).background(Color.White,RoundedCornerShape(20.dp)).padding(16.dp),content=content)}
@Composable fun Label(text:String){Text(text,color=Ink,fontWeight=FontWeight.SemiBold,fontSize=16.sp,modifier=Modifier.padding(bottom=12.dp))}
@Composable fun Numbers(reds:List<Int>,blue:Int,small:Boolean=false){Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(if(small)5.dp else 7.dp)){reds.forEach{Ball(it,Red,small)};Text("+",color=Muted,fontSize=14.sp);Ball(blue,Blue,small)}}
@Composable fun Ball(n:Int,color:Color,small:Boolean){Box(Modifier.size(if(small)29.dp else 36.dp).background(color,CircleShape),contentAlignment=Alignment.Center){Text("%02d".format(n),color=Color.White,fontWeight=FontWeight.Bold,fontSize=if(small)11.sp else 13.sp)}}
@Composable fun ChipRow(values:List<String>,selected:String,choose:(String)->Unit){Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.horizontalScroll(rememberScrollState())){values.forEach{v->val active=v==selected;Text(v,modifier=Modifier.border(1.dp,if(active)Green else Color(0xFFE6EBE7),RoundedCornerShape(50)).background(if(active)Color(0xFFE5F2ED)else Color.White,RoundedCornerShape(50)).clickable{choose(v)}.padding(horizontal=14.dp,vertical=8.dp),color=if(active)Green else Muted,fontSize=13.sp)}}}
@Composable fun SyncLine(syncing:Boolean,message:String,time:String,onSync:()->Unit){Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween,modifier=Modifier.fillMaxWidth()){Column(Modifier.weight(1f)){Text(if(syncing)"同步中" else if(message.isNotBlank())message else "官方数据 · ${if(time.isBlank())"等待同步" else "更新于 $time"}",fontSize=12.sp,color=if(message.startsWith("同步失败"))Red else Muted);Text("来源：中国福利彩票发行管理中心",fontSize=10.sp,color=Muted)};TextButton(onClick=onSync,enabled=!syncing){Text(if(syncing)"…" else "立即更新")}}}
@Composable fun Home(draws:List<Draw>,tickets:List<Ticket>,years:Int,amount:Int,mode:String,setYears:(Int)->Unit,setAmount:(Int)->Unit,setMode:(String)->Unit,generate:()->Unit,syncState:Triple<Boolean,String,String>,onSync:()->Unit){val(lastIssue, nextDate)=drawCalendar(draws.firstOrNull()?.date.orEmpty());PageScroll{
 Header("双色球智析","官方历史数据 · 统计模型参考")
 CardBox{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("候选号码",color=Muted,fontSize=13.sp);Text(if(tickets.isEmpty())"生成一组参考组合" else "本次综合评分组合",color=Ink,fontSize=19.sp,fontWeight=FontWeight.Bold)};Text("${draws.size} 期数据",color=Green,fontSize=12.sp)};Spacer(Modifier.height(18.dp));if(tickets.isEmpty())Text("选择分析策略后生成候选",color=Muted)else{Numbers(tickets.first().reds,tickets.first().blue);Spacer(Modifier.height(10.dp));Text("结构评分 ${tickets.first().score} / 100 · 不代表中奖概率",color=Muted,fontSize=12.sp)}}
 CardBox{Label("快速生成");Row(verticalAlignment=Alignment.CenterVertically){Text("范围",color=Muted);Spacer(Modifier.width(10.dp));ChipRow(listOf("1年","3年","5年","10年"),"${years}年"){setYears(it.dropLast(1).toInt())}};Spacer(Modifier.height(10.dp));Row(verticalAlignment=Alignment.CenterVertically){Text("组数",color=Muted);Spacer(Modifier.width(10.dp));ChipRow((1..10).map{"${it}组"},"${amount}组"){setAmount(it.dropLast(1).toInt())}};Spacer(Modifier.height(10.dp));ChipRow(listOf("综合模型","热号优先","冷热搭配","均衡型"),mode,setMode);Spacer(Modifier.height(14.dp));Button(onClick=generate,modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text("✦ 生成 $amount 组候选号码")}}
 CardBox{Label("最近一期官方开奖");if(draws.isNotEmpty()){val d=draws.first();Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("${d.issue} 期",fontWeight=FontWeight.SemiBold,color=Ink);Text(d.date,color=Muted,fontSize=12.sp)};Spacer(Modifier.height(12.dp));Numbers(d.reds,d.blue)}else Text("正在加载历史数据",color=Muted)}
 CardBox{Label("开奖日历");Text("双色球通常于周二、周四、周日开奖",color=Ink,fontSize=14.sp);Text("上期开奖：${lastIssue.ifBlank{"暂无"}}    ·    下期开奖日：$nextDate",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=6.dp))}
 CardBox{SyncLine(syncState.first,syncState.second,syncState.third,onSync)}
 Text("开奖具有随机性，频率、遗漏与历史回测仅描述过往数据，不构成预测保证。",color=Muted,fontSize=11.sp,modifier=Modifier.padding(horizontal=20.dp,vertical=8.dp))
}}

@Composable fun Analysis(draws:List<Draw>,years:Int,setYears:(Int)->Unit){val data=LotteryEngine.window(draws,years);val freq=LotteryEngine.frequency(data);val miss=LotteryEngine.misses(data);val sorted=(1..33).map{freq[it]}.sorted();val low=sorted[10];val high=sorted[22];val hot=(1..33).filter{freq[it]>high};val cold=(1..33).filter{freq[it]<low};val warm=(1..33).filter{freq[it] in low..high};PageScroll{Header("数据分析","按开奖年份统计 · ${data.size} 期样本");CardBox{Label("分析区间");ChipRow(listOf("1年","2年","3年","5年","10年"),"${years}年"){setYears(it.dropLast(1).toInt())}};CardBox{Label("红球出现频率排行");(1..33).sortedByDescending{freq[it]}.take(12).forEachIndexed{idx,n->Row(Modifier.fillMaxWidth().padding(vertical=5.dp),verticalAlignment=Alignment.CenterVertically){Text("%02d".format(n),color=Red,fontWeight=FontWeight.Bold,modifier=Modifier.width(38.dp));Box(Modifier.weight(1f).height(10.dp).clip(RoundedCornerShape(8.dp)).background(Color(0xFFF0F2EF))){Box(Modifier.fillMaxWidth(if(freq[n]==0)0f else freq[n].toFloat()/(freq.maxOrNull()?:1)).fillMaxHeight().background(if(idx<4)Red else Green,RoundedCornerShape(8.dp)))};Text(" ${freq[n]} 次",color=Muted,fontSize=12.sp,modifier=Modifier.width(56.dp))}}};CardBox{Label("冷热号分布");Text("热号  ${hot.size} 个：${hot.sorted().joinToString("、"){"%02d".format(it)}}",color=Red,fontSize=12.sp);Text("温号  ${warm.size} 个：${warm.sorted().joinToString("、"){"%02d".format(it)}}",color=Green,fontSize=12.sp,modifier=Modifier.padding(top=8.dp));Text("冷号  ${cold.size} 个：${cold.sorted().joinToString("、"){"%02d".format(it)}}",color=Blue,fontSize=12.sp,modifier=Modifier.padding(top=8.dp))};CardBox{Label("遗漏值排行");Text((1..33).sortedByDescending{miss[it]}.take(8).joinToString("    "){"%02d · %d期".format(it,miss[it])},color=Muted,fontSize=12.sp);Text("选取遗漏最长的红球",color=Muted,fontSize=10.sp,modifier=Modifier.padding(top=5.dp))};val last=data.firstOrNull();CardBox{Label("号码结构特征");if(last!=null){val odd=last.reds.count{it%2==1};val big=last.reds.count{it>=17};Text("最新一期 ${last.issue}：和值 ${last.reds.sum()} · 跨度 ${last.reds.last()-last.reds.first()} · 奇偶 $odd:${6-odd} · 大小 $big:${6-big} · 连号 ${LotteryEngine.consecutivePairs(last)} 组",color=Ink,fontSize=13.sp)};val sums=data.take(40).reversed().map{it.reds.sum().toFloat()};Text("近 40 期和值走势图",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=14.dp));MiniChart(sums,Red);Text("近 40 期跨度走势图",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=12.dp));MiniChart(data.take(40).reversed().map{(it.reds.last()-it.reds.first()).toFloat()},Blue)};CardBox{var selected by remember{mutableIntStateOf(1)};Label("红球遗漏走势图");ChipRow((1..33).map{"%02d".format(it)},"%02d".format(selected)){selected=it.toInt()};val trend=data.take(40).reversed().mapIndexed{idx,d->(data.take(40).reversed().take(idx+1).reversed().indexOfFirst{selected in it.reds}.let{if(it<0)40 else it}).toFloat()};MiniChart(trend,Green)} } }

@Composable fun MiniChart(values:List<Float>,color:Color){if(values.size<2){Text("数据不足",color=Muted);return};val max=(values.maxOrNull()?:1f).coerceAtLeast(1f);val min=values.minOrNull()?:0f;androidx.compose.foundation.Canvas(Modifier.fillMaxWidth().height(130.dp).padding(top=8.dp)){val pts=values.mapIndexed{i,v->androidx.compose.ui.geometry.Offset(i.toFloat()/(values.size-1)*size.width,size.height-(v-min+1)/(max-min+1)*size.height)};for(i in 0..3){val y=i*size.height/3;drawLine(Color(0xFFE8ECE8),androidx.compose.ui.geometry.Offset(0f,y),androidx.compose.ui.geometry.Offset(size.width,y),1.dp.toPx())};val path=Path().apply{moveTo(pts.first().x,pts.first().y);pts.drop(1).forEach{lineTo(it.x,it.y)}};drawPath(path,color,style=Stroke(width=3.dp.toPx()));pts.forEach{drawCircle(color,3.dp.toPx(),it)}}}

@Composable fun History(draws:List<Draw>,syncing:Boolean,message:String,time:String,onSync:()->Unit){var filter by remember{mutableStateOf("最近30期")};var query by remember{mutableStateOf("")};var year by remember{mutableStateOf("全部年份")};val years=remember(draws){listOf("全部年份")+draws.map{it.date.take(4)}.distinct().sortedDescending()};val count=when(filter){"最近50期"->50;"最近100期"->100;else->30};val filtered=draws.filter{(year=="全部年份"||it.date.startsWith(year))&&(query.isBlank()||it.issue.contains(query)||it.date.contains(query))}.let{if(filter.startsWith("近")){val n=filter.drop(1).dropLast(1).toIntOrNull()?:1;LotteryEngine.window(it,n)}else it.take(count)};PageScroll{Header("历史数据","${draws.size} 期 · 官方来源数据");CardBox{SyncLine(syncing,message,time,onSync);Spacer(Modifier.height(8.dp));ChipRow(listOf("最近30期","最近50期","最近100期","近1年","近3年","近5年"),filter){filter=it};Spacer(Modifier.height(10.dp));ChipRow(years,year){year=it};Spacer(Modifier.height(10.dp));OutlinedTextField(value=query,onValueChange={query=it},label={Text("查询期号或日期")},singleLine=true,modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp));Text("找到 ${filtered.size} 期",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=8.dp))};filtered.forEach{d->CardBox{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("${d.issue} 期",fontWeight=FontWeight.SemiBold,color=Ink);Text(d.date,color=Muted,fontSize=12.sp)};Spacer(Modifier.height(12.dp));Numbers(d.reds,d.blue,true)}}} }

@Composable fun Smart(draws:List<Draw>,years:Int,amount:Int,mode:String,setYears:(Int)->Unit,setAmount:(Int)->Unit,setMode:(String)->Unit,generate:()->Unit,generateFiltered:(Int,Int)->Unit,tickets:List<Ticket>){var custom by remember{mutableStateOf(false)};var sumMin by remember{mutableStateOf("60")};var sumMax by remember{mutableStateOf("150")};val result= remember(draws,mode,years){LotteryEngine.backtest(draws,mode,years)};PageScroll{Header("智能选号","候选生成 · 权重评分 · 历史回测");CardBox{Label("选号策略");ChipRow(listOf("综合模型","热号优先","冷热搭配","均衡型"),mode,setMode);Spacer(Modifier.height(14.dp));Label("数据窗口");ChipRow(listOf("1年","2年","3年","5年","10年"),"${years}年"){setYears(it.dropLast(1).toInt())};Spacer(Modifier.height(14.dp));Label("候选组数");ChipRow((1..10).map{"${it}组"},"${amount}组"){setAmount(it.dropLast(1).toInt())};Spacer(Modifier.height(8.dp));Row(verticalAlignment=Alignment.CenterVertically){Checkbox(custom,{custom=it});Text("启用和值筛选",color=Ink,fontSize=13.sp)};if(custom){Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(sumMin,{sumMin=it},label={Text("和值最小")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),modifier=Modifier.weight(1f),singleLine=true);OutlinedTextField(sumMax,{sumMax=it},label={Text("和值最大")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),modifier=Modifier.weight(1f),singleLine=true)}};Spacer(Modifier.height(12.dp));Button(onClick={if(custom){val min=sumMin.toIntOrNull()?.coerceIn(21,183)?:60;val max=sumMax.toIntOrNull()?.coerceIn(min,183)?:150;generateFiltered(min,max)}else generate()},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text("生成 $amount 组候选")}}
 CardBox{Label("综合评分权重");listOf("历史频率" to 26,"遗漏平衡" to 16,"和值结构" to 19,"奇偶与跨度" to 17,"蓝球频率" to 12,"连号结构" to 10).forEach{(name,w)->Row(Modifier.fillMaxWidth().padding(vertical=5.dp),verticalAlignment=Alignment.CenterVertically){Text(name,color=Ink,fontSize=13.sp,modifier=Modifier.width(105.dp));LinearProgressIndicator(progress={w/30f},modifier=Modifier.weight(1f).height(6.dp),color=Green,trackColor=Color(0xFFEFF2EF));Text(" $w%",color=Muted,fontSize=12.sp,modifier=Modifier.width(45.dp))}};Text("评分用于组合结构比较，不代表中奖概率。",color=Muted,fontSize=11.sp,modifier=Modifier.padding(top=10.dp))}
 if(tickets.isNotEmpty())CardBox{Label("本次候选组合");tickets.forEachIndexed{i,t->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("第 ${i+1} 组",color=Ink,fontWeight=FontWeight.SemiBold);Text("结构评分 ${t.score}",color=Green,fontSize=12.sp)};Spacer(Modifier.height(9.dp));Numbers(t.reds,t.blue,true);if(i<tickets.lastIndex)HorizontalDivider(Modifier.padding(vertical=12.dp),color=Color(0xFFEFF2EF))}}
 CardBox{Label("历史回测 · 最近 ${result.draws} 期");Text("红球命中 ${result.redHits} 次 · 蓝球命中 ${result.blueHits} 次",color=Ink,fontSize=14.sp);Text("每期平均命中 ${"%.2f".format(result.meanHits)} 个号码",color=Green,fontSize=18.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=8.dp));Text("总命中数分布：0 个 ${result.hit0}期 · 1 个 ${result.hit1}期 · 2 个 ${result.hit2}期 · 3 个及以上 ${result.hit3Plus}期",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=8.dp));Text("逐期向前滚动验证，每期只使用此前开奖数据。单组随机选号，回测仅作历史描述。",color=Muted,fontSize=11.sp,modifier=Modifier.padding(top=8.dp))}
 CardBox{Label("自定义条件");Text("和值范围支持输入；下一版可扩展奇偶比例、大小比例、连号上限、红球分区和排除历史组合。",color=Muted,fontSize=12.sp)}
} }

private fun drawCalendar(latestDate:String):Pair<String,String>{if(latestDate.isBlank())return "" to "待同步";return runCatching{val d=LocalDate.parse(latestDate,DateTimeFormatter.ISO_LOCAL_DATE);val next=(1..7).map{d.plusDays(it.toLong())}.first{it.dayOfWeek.value in listOf(2,4,7)};d.toString() to next.format(DateTimeFormatter.ofPattern("M月d日"))}.getOrDefault(latestDate to "以官网公告为准")}




